const listSupplierInvoices = `-- name: ListSupplierInvoices :many
SELECT 
    si.id, si.legal_entity_id, si.invoice_number, si.supplier_invoice_number, si.supplier_id, si.invoice_date, si.due_date, si.currency_code, si.exchange_rate, si.subtotal, si.discount_amount, si.taxable_amount, si.tax_amount, si.total_amount, si.status, si.payment_status, si.journal_entry_id, si.notes, si.created_by_user_id, si.created_at, si.updated_at,
    s.name_en AS supplier_name_en,
    s.name_ar AS supplier_name_ar,
    s.tax_id AS supplier_tax_id
FROM payables.supplier_invoices si
JOIN payables.suppliers s ON si.supplier_id = s.id
WHERE si.legal_entity_id = $1
  AND (
      $2::text = '' 
      OR si.invoice_number ILIKE '%' || $2 || '%'
      OR si.supplier_invoice_number ILIKE '%' || $2 || '%'
      OR s.name_en ILIKE '%' || $2 || '%'
      OR s.name_ar ILIKE '%' || $2 || '%'
  )
  AND ($3::uuid IS NULL OR si.supplier_id = $3)
  AND ($4::text = 'ALL' OR si.status = $4)
  AND ($5::text = 'ALL' OR si.payment_status = $5)
ORDER BY si.invoice_date DESC, si.created_at DESC
LIMIT $6 OFFSET $7
`

